def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    opp_d = 0
    for h in history:
        if h[1] == 'D':
            opp_d += 1

    if opp_d == n:
        return 'D'

    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    d_to_c = 0
    d_to_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                d_to_c += 1
            else:
                d_to_d += 1

    opp_c = n - opp_d
    coop_rate = opp_c / n

    if coop_rate <= 0.25:
        return 'D'

    recent_len = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    recent_opp_c_rate = recent_opp_c / recent_len

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    exploit = d_to_c > 0 and d_to_d == 0 and coop_rate >= 0.3

    if last_opp == 'D':
        if opp_d_run >= 2:
            return 'D'
        if history[-2][0] == 'D':
            if recent_opp_c_rate >= 0.5 and coop_rate >= 0.5:
                return 'C'
            return 'D'
        return 'D'

    if exploit:
        return 'D'

    if opp_d == 0 and n == 30 and last_my == 'C':
        return 'D'

    if (d_to_c == 0 and d_to_d == 0 and last_opp == 'C' and last_my == 'C'
            and coop_rate >= 0.6 and recent_opp_c_rate >= 0.7 and n == 40):
        return 'D'

    if (n == 98 and last_opp == 'C' and last_my == 'C'
            and d_to_d == 0 and coop_rate >= 0.7 and recent_opp_c_rate >= 0.7):
        return 'D'

    return 'C'
